static void inspect(Dwg_Object *o,unsigned depth){if(!o||depth>8)return;BITCODE_H owner=o->supertype==DWG_SUPERTYPE_ENTITY?o->tio.entity->ownerhandle:o->tio.object->ownerhandle;Dwg_Object *parent=dwg_ref_object(&drawing,owner);unsigned refs=0;for(unsigned i=0;i<drawing.num_object_refs;i++)if(drawing.object_ref[i]&&drawing.object_ref[i]->absolute_ref==o->handle.value)refs++;printf("%*s%s unknown=%u rest=%u owner=%s incoming=%u reactors=%u\n",depth*2,"",o->name,o->num_unknown_bits,o->num_unknown_rest,parent?parent->name:"NONE",refs,o->supertype==DWG_SUPERTYPE_ENTITY?o->tio.entity->num_reactors:o->tio.object->num_reactors);BITCODE_H dict=o->supertype==DWG_SUPERTYPE_ENTITY?o->tio.entity->xdicobjhandle:o->tio.object->xdicobjhandle;if(o->fixedtype==DWG_TYPE_DICTIONARY){Dwg_Object_DICTIONARY *d=o->tio.object->tio.DICTIONARY;for(unsigned i=0;i<d->numitems;i++)inspect(dwg_ref_object(&drawing,d->itemhandles[i]),depth+1);}else if(dict)inspect(dwg_ref_object(&drawing,dict),depth+1);}
int main(int argc,char **argv){if(argc!=3||pllato_open(argv[1])>=128)return 1;setbuf(stdout,NULL);printf("objects=%u\n",drawing.num_objects);BITCODE_HV h=strtoull(argv[2],NULL,16);Dwg_Object *o=dwg_resolve_handle(&drawing,h);if(!o)for(unsigned i=0;i<drawing.num_objects;i++)if(drawing.object[i].handle.value==h)o=&drawing.object[i];if(!o)puts("not found");else inspect(o,0);pllato_close();return 0;}
